#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    if (!(cin >> n >> m)) return 0;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    const long long INF = (1LL << 60);
    vector<long long> dp(2 * n + 1, INF);
    dp[n] = 0; // base balance 0 shifted by n

    for (int step = 0; step < n; ++step) {
        vector<long long> new_dp(2 * n + 1, INF);
        for (int bal = 0; bal <= 2 * n; ++bal) {
            if (dp[bal] == INF) continue;
            int real_bal = bal - n;
            // open bracket
            int nb_open = real_bal + 1;
            if (nb_open >= -n && nb_open <= n) {
                int idx = nb_open + n;
                new_dp[idx] = min(new_dp[idx], dp[bal] + a[step]);
            }
            // close bracket if possible
            if (real_bal > 0) {
                int nb_close = real_bal - 1;
                int idx = nb_close + n;
                new_dp[idx] = min(new_dp[idx], dp[bal] + b[step]);
            }
        }
        dp.swap(new_dp);
    }

    // Build matrix M of size (2n+1) x (2n+1)
    int sz = 2 * n + 1;
    vector<vector<long long>> M(sz, vector<long long>(sz, INF));
    for (int start = 0; start < sz; ++start) {
        vector<long long> dp2(sz, INF);
        dp2[start] = 0;
        for (int step = 0; step < n; ++step) {
            vector<long long> new_dp2(sz, INF);
            for (int bal = 0; bal < sz; ++bal) {
                if (dp2[bal] == INF) continue;
                int real_bal = bal - n;
                // open
                int nb_open = real_bal + 1;
                if (nb_open >= -n && nb_open <= n) {
                    int idx = nb_open + n;
                    new_dp2[idx] = min(new_dp2[idx], dp2[bal] + a[step]);
                }
                // close
                if (real_bal > 0) {
                    int nb_close = real_bal - 1;
                    int idx = nb_close + n;
                    new_dp2[idx] = min(new_dp2[idx], dp2[bal] + b[step]);
                }
            }
            dp2.swap(new_dp2);
        }
        for (int end = 0; end < sz; ++end) {
            M[start][end] = dp2[end];
        }
    }

    // Matrix exponentiation in min-plus semiring
    auto mat_mul = [&](const vector<vector<long long>>& A, const vector<vector<long long>>& B) {
        vector<vector<long long>> C(sz, vector<long long>(sz, INF));
        for (int i = 0; i < sz; ++i) {
            for (int k = 0; k < sz; ++k) {
                if (A[i][k] == INF) continue;
                for (int j = 0; j < sz; ++j) {
                    if (B[k][j] == INF) continue;
                    C[i][j] = min(C[i][j], A[i][k] + B[k][j]);
                }
            }
        }
        return C;
    };

    vector<vector<long long>> result(sz, vector<long long>(sz, INF));
    for (int i = 0; i < sz; ++i) result[i][i] = 0; // Identity matrix

    long long p = m;
    vector<vector<long long>> base = M;
    while (p > 0) {
        if (p & 1LL) result = mat_mul(result, base);
        base = mat_mul(base, base);
        p >>= 1LL;
    }

    cout << result[n][n] << "\n";
    return 0;
}
